@push('scripts')@if(request('view')!=='list')<script>let index=0;function addItem(){if(index>=30)return;const row=document.createElement('div');row.className='quote-item-row';row.innerHTML=`<div><label>Ürün / hizmet</label><input name="items[${index}][description]" required maxlength="300"></div><div><label>Adet</label><input type="number" name="items[${index}][quantity]" min="1" max="10000" value="1" required></div><div><label>Birim fiyat</label><input type="number" name="items[${index}][price]" min="0" step="0.0001" required></div><button class="button-remove" type="button" aria-label="Kalemi kaldır" onclick="this.parentElement.remove()">×</button>`;document.getElementById('items').appendChild(row);index++}addItem();
const companies={{Illuminate\Support\Js::from($companies)}};
const recipient=document.getElementById('recipient');
function showRecipient(){const selected=companies.find(c=>String(c.id)===recipient.value);document.getElementById('recipient-details').textContent=selected?[selected.name,selected.address,selected.email,selected.phone,selected.tax_office,selected.tax_number].filter(Boolean).join(' · '):'Müşteri seçildiğinde firma bilgileri burada gösterilir.';}
recipient.addEventListener('change',showRecipient);showRecipient();</script>@endif@endpush